/*
 * Zilog System 8000 CPU-A monitor, version 3.0
 *
 * Reassembled from the four 2732 EPROMs on the CPU-A board:
 *   cpu_34-0715-03a.u76  cpu_34-0716-03a.u74   image 0x0000..0x1fff
 *   cpu_34-0718-03a.u77  cpu_34-0717-03a.u75   image 0x2000..0x3fff
 * u76/u77 supply the even (high) bytes, u74/u75 the odd (low) bytes.
 *
 * The Z8001 comes out of reset segmented, but the monitor drops to
 * non-segmented operation at 0x0078 and stays there, so the image
 * assembles as Z8002 code throughout.
 *
 * Generated by tools/gen.py from regions.txt, equates.txt and
 * annotations.txt; `make verify` proves the result rebuilds the four
 * EPROM images byte for byte.
 */

	unsegm

	.equ	sio0a_data,0xff81                         /* serial channel A data */
	.equ	sio0b_data,0xff83                         /* serial channel B data   -- monitor console */
	.equ	sio0a_ctl,0xff85                          /* serial channel A control */
	.equ	sio0b_ctl,0xff87                          /* serial channel B control -- monitor console */
	.equ	ctc0_ch0,0xffa1                           /* baud-rate clock for SIO0 channel A */
	.equ	ctc0_ch1,0xffa3                           /* baud-rate clock for SIO0 channel B (console) */
	.equ	ctc0_ch2,0xffa5
	.equ	ctc0_ch3,0xffa7
	.equ	scr,0xffc1                                /* system configuration register; high nibble = DIP switches */
	.equ	sbr,0xffc9                                /* system boot / bus request register */
	.equ	nbr,0xffd1
	.equ	snvr,0xffd9                               /* NMI reason register */
	.equ	reti_ack,0xffe1                           /* write acknowledges RETI to the ZBI daisy chain */
	.equ	soft_reset,0xffe9
	.equ	monstack,0x40a0                           /* monitor stack top; grows down into the zeroed area */
	.equ	cksum,0x40af                              /* running checksum maintained by the hex-out routine */
	.equ	cmdbuf,0x40b0                             /* 0x80-byte command line, space-filled at reset */
	.equ	outbuf,0x4130                             /* text assembled here, then shipped by putbuf */
	.equ	rxqueue,0x41b0                            /* 256-byte receive ring filled by the SIO interrupt */
	.equ	rx_savedr1,0x439a
	.equ	cmdlen,0x439c                             /* characters accepted into cmdbuf */
	.equ	outlen,0x439e                             /* bytes pending in outbuf */
	.equ	rxcount,0x43a0                            /* unread characters in rxqueue */
	.equ	rxhead,0x43a4                             /* rxqueue read index */
	.equ	iopb,0x43b8                               /* I/O parameter block handed to the disk/tape drivers */
	.equ	iovec_read,0x43ba                         /* installed driver entry: read */
	.equ	iovec_write,0x43bc                        /* installed driver entry: write */
	.equ	flags,0x43f0                              /* bit 1 = output held off (XOFF), bit 2 = suppress output */
	.equ	flags2,0x43f1                             /* bit 3 = pass lower case through, bit 4, bit 2 = ... */
	.equ	ch_backspace,0x43f2                       /* editing and flow-control characters, initialised */
	.equ	ch_delete,0x43f3                          /* from ctrlchar_init at reset */
	.equ	ch_xon,0x43f4
	.equ	ch_xoff,0x43f5
	.equ	ch_prompt,0x43fe                          /* character written to announce the command prompt */
	.equ	psa,0x4400                                /* program status area installed with LDCTL PSAPOFF */

	.text


/* --------------------------------------------------------------------
 * The Z8001 fetches its initial status from the program status area at
 * physical 0x0000 on reset.  The segmented format is four words: a
 * reserved word, the flag/control word, then the program counter as
 * segment and offset.  FCW 0xc000 means segmented, system mode, all
 * interrupts disabled; the monitor gives that up almost immediately.
 -------------------------------------------------------------------- */
reset_psa:
	.word	0x0000                                   /* 0000: 0000 */
	.word	0xc000                                   /* 0002: c000  -- FCW: SEG | S/N -- segmented, system mode */
	.word	0x8000                                   /* 0004: 8000  -- PC segment 0 (0x8000 encodes "segment 0" in a long address) */
	.word	reset                                    /* 0006: 0070  -- PC offset -> reset */

/* --------------------------------------------------------------------
 * Not printed by the monitor -- the ROM part number and copyright are
 * here so a memory dump of the first block identifies the firmware.
 -------------------------------------------------------------------- */
msg_copyright:
	.ascii	"COPYRIGHT, ZILOG, INC. 1984 "          /* 0008 */
msg_banner:
	.word	47                                       /* 0024: 47 bytes of text follow */
	.ascii	"S8000 Monitor 3.0 - Press START to Load System"
	.byte	0x0d
	.byte	0x00
rom_entry_vec:
	.word	getc                                     /* 0056: 0a4a */
	.word	conout                                   /* 0058: 0a68 */
	.word	getedit                                  /* 005a: 09d8 */
	.word	crlf                                     /* 005c: 0a80 */
	.word	putmsg                                   /* 005e: 050c */
	.word	puthex16                                 /* 0060: 0540 */
	.word	putline                                  /* 0062: 0594 */
	.word	puthex8                                  /* 0064: 0544 */
	.word	L_0398                                   /* 0066: 0398 */
	.word	L_03a4                                   /* 0068: 03a4 */
	.word	L_11aa                                   /* 006a: 11aa */
	.word	L_0cae                                   /* 006c: 0cae */
	.word	cmdloop                                  /* 006e: 016c */

/* --------------------------------------------------------------------
 * Power-on entry.  Everything below runs with interrupts off until the
 * PSA has been installed.
 *
 * The board leaves reset with the monitor EPROMs at 0x0000..0x3fff and
 * 2 KB of local static RAM at 0x4000..0x47ff; off-board memory and the
 * three MMUs stay disabled until the system configuration register says
 * otherwise.  The monitor never turns them on for itself -- it runs
 * entirely out of local RAM so that it survives a wild program.
 -------------------------------------------------------------------- */
reset:
	clr	r14                                        /* 0070: 8de8  -- PSAP segment 0 */
	ldctl	psapseg,r14                              /* 0072: 7dec */
	ld	r1,#0x4000                                  /* 0074: 2101 4000  -- FCW: S/N only -- leave segmented mode */
	ldctl	fcw,r1                                   /* 0078: 7d1a  -- from here on the CPU is a Z8002 for all practical purposes */
	clr	r3                                         /* 007a: 8d38 */
	sout	#0xf0,r3                                  /* 007c: 3b37 00f0  -- clear MMU register 0 via the special I/O space */

/* --------------------------------------------------------------------
 * Console baud rate comes from two DIP switches in the top nibble of the
 * system configuration register (U70:1,4).  The nibble also carries the
 * boot-device selection in its other two bits, which the B command reads
 * back later.
 -------------------------------------------------------------------- */
	inb	rl3,#scr                                   /* 0080: 3ab4 ffc1  -- SCR, high nibble = DIP switches */
	.word	0xb2b1, 0xfffc                           /* 0084: srlb rl3,#0x4  -- shift the switch nibble down (raw .word: see escapes.txt) */
	andb	rl3,#0x3                                  /* 0088: 060b 0303  -- keep the two baud-rate bits */
	ldb	rl0,0x2f0(r3)                              /* 008c: 6038 02f0  -- CTC time constant for that rate */

/* --------------------------------------------------------------------
 * Both console CTC channels are set to counter mode with "time constant
 * follows" and reset asserted, then handed the divisor.  The CTC counts
 * a 1.2288 MHz clock and the SIO is programmed for a x64 sample rate, so
 * e.g. 9600 baud needs 1228800 / (9600*64) = 2.
 -------------------------------------------------------------------- */
	ldb	rl1,#0x47                                  /* 0090: c947  -- CTC control: reset, time constant follows, counter mode */
	outb	#ctc0_ch1,rl1                             /* 0092: 3a96 ffa3 */
	outb	#ctc0_ch1,rl0                             /* 0096: 3a86 ffa3 */
	outb	#ctc0_ch0,rl1                             /* 009a: 3a96 ffa1 */
	outb	#ctc0_ch0,rl0                             /* 009e: 3a86 ffa1 */

/* --------------------------------------------------------------------
 * Channel B is the console, and gets the longer setup string because it
 * also carries the interrupt vector for the pair.
 -------------------------------------------------------------------- */
	ld	r2,#0x202                                   /* 00a2: 2102 0202  -- 11-byte SIO setup string for channel B */
	ld	r0,#0xb                                     /* 00a6: 2100 000b */
	ld	r1,#sio0b_ctl                               /* 00aa: 2101 ff87  -- channel B control port */
	otirb	@r1,@r2,r0                               /* 00ae: 3a22 0010 */
	ld	r2,#0x20e                                   /* 00b2: 2102 020e  -- 9-byte SIO setup string for channel A */
	ld	r0,#0x9                                     /* 00b6: 2100 0009 */
	ld	r1,#sio0a_ctl                               /* 00ba: 2101 ff85  -- channel A control port */
	otirb	@r1,@r2,r0                               /* 00be: 3a22 0010 */
	ld	r1,#0x0                                     /* 00c2: 2101 0000  -- no DRAM refresh -- local RAM is static */
	ldctl	refresh,r1                               /* 00c6: 7d1b */
	ld	0x43e4,r1                                   /* 00c8: 6f01 43e4 */

/* --------------------------------------------------------------------
 * Zero local RAM by writing one word and rippling it upwards with LDIR.
 -------------------------------------------------------------------- */
	ld	r4,#0x4000                                  /* 00cc: 2104 4000  -- first word of local RAM */
	ld	r2,#0x4002                                  /* 00d0: 2102 4002 */
	ld	@r4,#0x0                                    /* 00d4: 0d45 0000 */
	ld	r1,#0x200                                   /* 00d8: 2101 0200 */
	ldir	@r2,@r4,r1                                /* 00dc: bb41 0120 */

/* --------------------------------------------------------------------
 * A second, shorter pass over the same region.  The first LDIR already
 * covered 0x4000..0x4401; this one repeats the bottom 64 bytes.
 -------------------------------------------------------------------- */
	ld	r4,#0x4000                                  /* 00e0: 2104 4000 */
	ld	r2,#0x4002                                  /* 00e4: 2102 4002 */
	ld	@r4,#0x0                                    /* 00e8: 0d45 0000 */
	ld	r1,#0x20                                    /* 00ec: 2101 0020 */
	ldir	@r2,@r4,r1                                /* 00f0: bb41 0120 */

/* --------------------------------------------------------------------
 * Blank the command line buffer with spaces rather than zeros so that a
 * recalled line is padded, not truncated.
 -------------------------------------------------------------------- */
	ld	cmdbuf,#0x2020                              /* 00f4: 4d05 40b0 2020  -- two spaces */
	ld	r4,#cmdbuf                                  /* 00fa: 2104 40b0 */
	ld	r2,#0x40b2                                  /* 00fe: 2102 40b2 */
	ld	r1,#0x80                                    /* 0102: 2101 0080 */
	ldir	@r2,@r4,r1                                /* 0106: bb41 0120 */
	ld	r4,#0x1f4                                   /* 010a: 2104 01f4  -- editing/flow-control character defaults -> 0x43f2 */
	ld	r2,#ch_backspace                            /* 010e: 2102 43f2 */
	ldk	r1,#0x7                                    /* 0112: bd17 */
	ldir	@r2,@r4,r1                                /* 0114: bb41 0120 */
	ld	r4,#0x250                                   /* 0118: 2104 0250  -- trap and interrupt vectors -> 0x4400 */
	ld	r2,#psa                                     /* 011c: 2102 4400 */
	ld	r1,#0x48                                    /* 0120: 2101 0048 */
	ldir	@r2,@r4,r1                                /* 0124: bb41 0120 */
	ld	r14,#0x8000                                 /* 0128: 210e 8000 */
	ld	r15,#0x4020                                 /* 012c: 210f 4020 */
	ldl	0x43da,rr14                                /* 0130: 5d0e 43da */
	ld	r15,#monstack                               /* 0134: 210f 40a0 */
	ld	r1,#psa                                     /* 0138: 2101 4400  -- install the program status area */
	ldctl	psapoff,r1                               /* 013c: 7d1d */
	ld	0x43ea,r14                                  /* 013e: 6f0e 43ea */
	ld	0x43de,r14                                  /* 0142: 6f0e 43de */
	ld	0x43ec,r1                                   /* 0146: 6f01 43ec */
	ld	0x43e0,#0x8000                              /* 014a: 4d05 43e0 8000 */
	ld	0x43e2,#0xc000                              /* 0150: 4d05 43e2 c000 */
	setb	flags2,#0x3                               /* 0156: 6403 43f1  -- flags2 bit 3 -- accept lower case as typed */
	resb	flags2,#0x4                               /* 015a: 6204 43f1  -- flags2 bit 4 -- clear */
	call	crlf                                      /* 015e: 5f00 0a80  -- CR/LF */
	ld	r2,#msg_banner                              /* 0162: 2102 0024  -- "S8000 Monitor 3.0 - Press START to Load System" */
	call	putmsg                                    /* 0166: 5f00 050c */
	ei	vi                                          /* 016a: 7c05  -- vectored interrupts on; the console SIO can now interrupt */

/* --------------------------------------------------------------------
 * Every command returns here.  The stack pointer is reloaded from
 * scratch each time round so that a command that unbalanced the stack
 * (or a breakpoint taken inside one) cannot wedge the monitor, and the
 * loop address is pushed as the return address for the dispatched
 * handler -- handlers exit with a plain RET.
 -------------------------------------------------------------------- */
cmdloop:
	ld	r15,#monstack                               /* 016c: 210f 40a0  -- reset the monitor stack (grows down from 0x40a0) */
	push	@r15,#cmdloop                             /* 0170: 0df9 016c  -- handlers RET straight back into the loop */
	ldb	rl1,flags                                  /* 0174: 6009 43f0  -- keep only the two live flag bits */
	and	r1,#0x6                                    /* 0178: 0701 0006 */
	ldb	flags,rl1                                  /* 017c: 6e09 43f0 */
	ldb	rl0,ch_prompt                              /* 0180: 6008 43fe  -- prompt character (a space by default) */
	call	conout                                    /* 0184: 5f00 0a68  -- write the prompt */
	call	getcmdline                                /* 0188: 5f00 0a8c  -- read one edited command line */
	jr	ne,L_0196                                   /* 018c: ee04  -- non-empty line -> use its first character */
	bitb	flags2,#0x2                               /* 018e: 6602 43f1 */
	jr	eq,L_0196                                   /* 0192: e601 */
	ldb	rl0,#0x4e                                  /* 0194: c84e  -- empty line repeats as "N" (next) */
L_0196:
	resb	flags2,#0x2                               /* 0196: 6202 43f1 */

/* --------------------------------------------------------------------
 * The command letter is looked up by scanning the letter table backwards
 * with CPDRB.  On a match r1 holds the number of entries left, which is
 * exactly the index of the matched letter counted from the start of the
 * table -- so it doubles as the index into the parallel address table.
 -------------------------------------------------------------------- */
	ld	r1,#0x10                                    /* 019a: 2101 0010  -- 16 bytes to scan */
	lda	r2,0x1b1(r1)                               /* 019e: 7612 01b1  -- one past the end of cmd_letters */
	cpdrb	rl0,@r2,r1,eq                            /* 01a2: ba2c 0186  -- scan down for the command letter */
	jr	ne,cmd_error                                /* 01a6: ee1c  -- unknown letter */
	sll	r1,#0x1                                    /* 01a8: b311 0001  -- word index */
	ld	r2,0x1c2(r1)                                /* 01ac: 6112 01c2  -- handler address */
	jp	t,@r2                                       /* 01b0: 1e28  -- enter the command handler */

/* --------------------------------------------------------------------
 * 15 command letters plus a trailing NUL, so that the 16-entry scan
 * always terminates.  Index = offset from the start of the table.
 -------------------------------------------------------------------- */
cmd_letters:
	.byte	0x42, 0x43, 0x44, 0x46, 0x47, 0x49       /* 01b2: BCDFGI */
	.byte	0x4a, 0x4c, 0x4d, 0x4e, 0x54, 0x51       /* 01b8: JLMNTQ */
	.byte	0x52, 0x5a, 0x50, 0x00                   /* 01be: RZP. */

/* --------------------------------------------------------------------
 * Parallel to cmd_letters: B C D F G I J L M N T Q R Z P.
 -------------------------------------------------------------------- */
cmd_dispatch:
	.word	cmd_B                                    /* 01c2: 0c3e */
	.word	cmd_C                                    /* 01c4: 033e */
	.word	cmd_D                                    /* 01c6: 03b2 */
	.word	cmd_F                                    /* 01c8: 02f4 */
	.word	cmd_G                                    /* 01ca: 0b54 */
	.word	cmd_I                                    /* 01cc: 06d4 */
	.word	cmd_J                                    /* 01ce: 0b42 */
	.word	cmd_L                                    /* 01d0: 0dc2 */
	.word	cmd_M                                    /* 01d2: 0316 */
	.word	cmd_N                                    /* 01d4: 0bc6 */
	.word	cmd_T                                    /* 01d6: 148e */
	.word	cmd_Q                                    /* 01d8: 0bf8 */
	.word	cmd_R                                    /* 01da: 07a6 */
	.word	cmd_Z                                    /* 01dc: 1294 */
	.word	cmd_P                                    /* 01de: 06de */
cmd_error:
	ldb	rl0,#0x3f                                  /* 01e0: c83f  -- '?' */
	call	conout                                    /* 01e2: 5f00 0a68 */
	ld	outlen,#0x0                                 /* 01e6: 4d05 439e 0000  -- discard any pending output */
	ld	r15,#monstack                               /* 01ec: 210f 40a0 */
	jp	t,cmdloop                                   /* 01f0: 5e08 016c */

/* --------------------------------------------------------------------
 * Seven words copied to 0x43f2.  The first four are the line-editing and
 * flow-control characters: backspace, delete, XON, XOFF.  The last byte
 * of the block is the prompt character, a space.
 -------------------------------------------------------------------- */
ctrlchar_init:
	.byte	0x08, 0x7f, 0x11, 0x13, 0x00, 0x00       /* 01f4: ...... */
	.byte	0x7f, 0x00, 0x00, 0x04, 0x00, 0x01       /* 01fa: ...... */
	.byte	0x20, 0x00                               /* 0200:  . */

/* --------------------------------------------------------------------
 * Z80 SIO setup strings.  Each byte pair is a write-register select
 * followed by its value; a lone byte is a WR0 command.
 *   18            WR0: channel reset
 *   02 10         WR2: interrupt vector base 0x10
 *   14 cc         WR4: x64 clock, 2 stop bits, no parity
 *   03 c1         WR3: 8 data bits, receiver enable
 *   05 ea         WR5: 8 data bits, transmitter enable, RTS+DTR
 *   11 1c         WR1: interrupt on every received character,
 *                      status affects vector
 -------------------------------------------------------------------- */
sio_init_chb:
	.byte	0x18, 0x02, 0x10, 0x14, 0xcc, 0x03       /* 0202: ...... */
	.byte	0xc1, 0x05, 0xea, 0x11, 0x1c, 0x00       /* 0208: ...... */

/* --------------------------------------------------------------------
 * As above but without the vector (WR2 is shared by both channels) and
 * with WR1 = 0x18, so channel A does not modify the vector.
 -------------------------------------------------------------------- */
sio_init_cha:
	.byte	0x18, 0x14, 0xcc, 0x03, 0xc1, 0x05       /* 020e: ...... */
	.byte	0xea, 0x11, 0x18, 0x00                   /* 0214: .... */

/* --------------------------------------------------------------------
 * Every trap and interrupt vector the monitor does not itself use points
 * here.  The handler reports the vector it was entered through so that a
 * stray interrupt from an unconfigured board can be identified.
 -------------------------------------------------------------------- */
trap_uninit_vector:
	ld	r5,@r15                                     /* 0218: 21f5 */
	ld	r2,#msg_uninit_vec                          /* 021a: 2102 022e  -- " UNINITIALIZED VECTOR ENTRY  ID= " */
	call	putmsg                                    /* 021e: 5f00 050c */
	call	puthex16                                  /* 0222: 5f00 0540 */
	call	putline                                   /* 0226: 5f00 0594 */
	jp	t,cmdloop                                   /* 022a: 5e08 016c */
msg_uninit_vec:
	.word	32                                       /* 022e: 32 bytes of text follow */
	.ascii	"UNINITIALIZED VECTOR ENTRY  ID= "

/* --------------------------------------------------------------------
 * Copied to 0x4400 and installed as the program status area.  The layout
 * is the Z8001 segmented one -- four words per trap: reserved, FCW, PC
 * segment, PC offset -- because the PSA format follows the CPU type, not
 * the current mode.  Every entry loads FCW 0x4000, so traps are taken in
 * non-segmented system mode, except the system call which is entered
 * segmented (0xc000).
 *
 *   +0x08  unimplemented instruction -> trap_uninit_vector
 *   +0x10  privileged instruction    -> trap_uninit_vector
 *   +0x18  system call               -> 0x0f2c, segmented
 *   +0x20  segment trap              -> trap_uninit_vector
 *   +0x28  non-maskable interrupt    -> 0x12fc
 *   +0x30  non-vectored interrupt    -> trap_uninit_vector
 *   +0x38  vectored interrupt        -> trap_uninit_vector
 *   +0x40  vectored interrupt table, two words per entry, byte offset
 *          2 x the vector supplied by the device
 *
 * The four live vector-table entries are the console SIO's:
 *   vector 0x12 -> 0x0abc   channel B external/status
 *   vector 0x14 -> 0x10c0   channel B receive     (console input)
 *   vector 0x1a -> 0x1090   channel A external/status
 *   vector 0x1c -> 0x10ca   channel A receive
 -------------------------------------------------------------------- */
psa_template:
	.word	0x0000                                   /* 0250: 0000 */
	.word	0x0000                                   /* 0252: 0000 */
	.word	0x0000                                   /* 0254: 0000 */
	.word	0x0000                                   /* 0256: 0000 */
	.word	0x0000                                   /* 0258: 0000 */
	.word	0x4000                                   /* 025a: 4000 */
	.word	0x8000                                   /* 025c: 8000 */
	.word	trap_uninit_vector                       /* 025e: 0218 */
	.word	0x0000                                   /* 0260: 0000 */
	.word	0x4000                                   /* 0262: 4000 */
	.word	0x8000                                   /* 0264: 8000 */
	.word	trap_uninit_vector                       /* 0266: 0218 */
	.word	0x0000                                   /* 0268: 0000 */
	.word	0xc000                                   /* 026a: c000 */
	.word	0x8000                                   /* 026c: 8000 */
	.word	trap_syscall                             /* 026e: 0f2c */
	.word	0x0000                                   /* 0270: 0000 */
	.word	0x4000                                   /* 0272: 4000 */
	.word	0x8000                                   /* 0274: 8000 */
	.word	trap_uninit_vector                       /* 0276: 0218 */
	.word	0x0000                                   /* 0278: 0000 */
	.word	0x4000                                   /* 027a: 4000 */
	.word	0x8000                                   /* 027c: 8000 */
	.word	trap_nmi                                 /* 027e: 12fc */
	.word	0x0000                                   /* 0280: 0000 */
	.word	0x4000                                   /* 0282: 4000 */
	.word	0x8000                                   /* 0284: 8000 */
	.word	trap_uninit_vector                       /* 0286: 0218 */
	.word	0x0000                                   /* 0288: 0000 */
	.word	0x4000                                   /* 028a: 4000 */
	.word	0x8000                                   /* 028c: 8000 */
	.word	trap_uninit_vector                       /* 028e: 0218 */
	.word	0x8000                                   /* 0290: 8000 */
	.word	trap_uninit_vector                       /* 0292: 0218 */
	.word	0x8000                                   /* 0294: 8000 */
	.word	trap_uninit_vector                       /* 0296: 0218 */
	.word	0x8000                                   /* 0298: 8000 */
	.word	trap_uninit_vector                       /* 029a: 0218 */
	.word	0x8000                                   /* 029c: 8000 */
	.word	trap_uninit_vector                       /* 029e: 0218 */
	.word	0x8000                                   /* 02a0: 8000 */
	.word	trap_uninit_vector                       /* 02a2: 0218 */
	.word	0x8000                                   /* 02a4: 8000 */
	.word	trap_uninit_vector                       /* 02a6: 0218 */
	.word	0x8000                                   /* 02a8: 8000 */
	.word	trap_uninit_vector                       /* 02aa: 0218 */
	.word	0x8000                                   /* 02ac: 8000 */
	.word	trap_uninit_vector                       /* 02ae: 0218 */
	.word	0x8000                                   /* 02b0: 8000 */
	.word	trap_uninit_vector                       /* 02b2: 0218 */
	.word	0x8000                                   /* 02b4: 8000 */
	.word	int_sio0b_status                         /* 02b6: 0abc */
	.word	0x8000                                   /* 02b8: 8000 */
	.word	int_sio0b_rx                             /* 02ba: 10c0 */
	.word	0x8000                                   /* 02bc: 8000 */
	.word	trap_uninit_vector                       /* 02be: 0218 */
	.word	0x8000                                   /* 02c0: 8000 */
	.word	trap_uninit_vector                       /* 02c2: 0218 */
	.word	0x8000                                   /* 02c4: 8000 */
	.word	int_sio0a_status                         /* 02c6: 1090 */
	.word	0x8000                                   /* 02c8: 8000 */
	.word	int_sio0a_rx                             /* 02ca: 10ca */
	.word	0x8000                                   /* 02cc: 8000 */
	.word	trap_uninit_vector                       /* 02ce: 0218 */
	.word	0x8000                                   /* 02d0: 8000 */
	.word	trap_uninit_vector                       /* 02d2: 0218 */
	.word	0x8000                                   /* 02d4: 8000 */
	.word	trap_uninit_vector                       /* 02d6: 0218 */
	.word	0x8000                                   /* 02d8: 8000 */
	.word	trap_uninit_vector                       /* 02da: 0218 */
	.word	0x8000                                   /* 02dc: 8000 */
	.word	trap_uninit_vector                       /* 02de: 0218 */
	.word	0x8000, 0x0218, 0x8000, 0x0218           /* 02e0: ........ */
	.word	0x8000, 0x0218, 0x8000, 0x0218           /* 02e8: ........ */

/* --------------------------------------------------------------------
 * CTC time constants: 300, 1200, 9600, 19200 baud, in DIP-switch order.
 -------------------------------------------------------------------- */
baud_table:
